    return pattern.casefold() in title.casefold()


def _classify_title(title: str) -> str | None:
    normalized = title.casefold()
    if any(
        _matches_contains(normalized, pattern)
        for pattern, _name, _priority in PRACTICE_PRIVATE_PATTERNS
    ):
        return "PRIVATE"
