def resolve_import_event_visibility(
    calendar: ExternalCalendarAccount,
    *,
    title: str,
    fallback: str | None = None,
) -> str:
    event_title = str(title or "")
    rules = getattr(calendar, "_prefetched_objects_cache", {}).get(
        "import_visibility_rules"
    )
    if rules is None:
        rules = calendar.import_visibility_rules.filter(is_active=True).order_by(
